import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";

interface DocumentEditorProps {
    studioPro: StudioProApi;
    documentId: string;
}

// Creates a standard IComponent that renders a React component into the root element; used across all editor components (agent, model, consumedMCPService, etc.)

export function createDocumentEditorComponent(
    AppComponent: React.ComponentType<DocumentEditorProps>
): IComponent {
    return {
        async loaded(componentContext: ComponentContext, componentInput: { documentId: string; dialogId?: string }) {
            const studioPro = getStudioProApi(componentContext);
            const { documentId } = componentInput;

            const rootElement = document.getElementById("root");
            if (!rootElement) throw new Error("Failed to find the root element");

            const root = createRoot(rootElement);

            root.render(
                <StrictMode>
                    {documentId == null ? (
                        <span>Document not found</span>
                    ) : (
                        <AppComponent studioPro={studioPro} documentId={documentId} />
                    )}
                </StrictMode>
            );
        }
    };
}
